struct sk_buff *sock_alloc_send_pskb(struct sock *sk, unsigned long header_len, /* <=== sock_alloc_send_pskb */ 
				     unsigned long data_len, int noblock,
				     int *errcode, int max_page_order)
{
	struct sk_buff *skb = NULL;
	unsigned long chunk;
	gfp_t gfp_mask;
	long timeo;
	int err;
	int npages = (data_len + (PAGE_SIZE - 1)) >> PAGE_SHIFT;
	struct page *page;
	int i;

	err = -EMSGSIZE;
	if (npages > MAX_SKB_FRAGS)
		goto failure;

	timeo = sock_sndtimeo(sk, noblock);
	while (!skb) {
		err = sock_error(sk);
		if (err != 0)
			goto failure;

		err = -EPIPE;
		if (sk->sk_shutdown & SEND_SHUTDOWN)
			goto failure;

		if (atomic_read(&sk->sk_wmem_alloc) >= sk->sk_sndbuf) {
			set_bit(SOCK_ASYNC_NOSPACE, &sk->sk_socket->flags);
			set_bit(SOCK_NOSPACE, &sk->sk_socket->flags);
			err = -EAGAIN;
			if (!timeo)
				goto failure;
			if (signal_pending(current))
				goto interrupted;
			timeo = sock_wait_for_wmem(sk, timeo);
			continue;
		}

		err = -ENOBUFS;
		gfp_mask = sk->sk_allocation;
		if (gfp_mask & __GFP_WAIT)
			gfp_mask |= __GFP_REPEAT;

		skb = alloc_skb(header_len, gfp_mask);
		if (!skb)
			goto failure;

		skb->truesize += data_len;

		for (i = 0; npages > 0; i++) {
			int order = max_page_order;

			while (order) {
				if (npages >= 1 << order) {
					page = alloc_pages(sk->sk_allocation |
							   __GFP_COMP | __GFP_NOWARN,
							   order);
					if (page)
						goto fill_page;
				}
				order--;
			}
			page = alloc_page(sk->sk_allocation);
			if (!page)
				goto failure;
fill_page:
			chunk = min_t(unsigned long, data_len,
				      PAGE_SIZE << order);
			skb_fill_page_desc(skb, i, page, 0, chunk);
			data_len -= chunk;
			npages -= 1 << order;
		}
	}

	skb_set_owner_w(skb, sk);
	return skb;

interrupted:
	err = sock_intr_errno(timeo);
failure:
	kfree_skb(skb);
	*errcode = err;
	return NULL;
}

unsigned char *skb_put(struct sk_buff *skb, unsigned int len) /* <=== skb_put */ 
{
	unsigned char *tmp = skb_tail_pointer(skb);
	SKB_LINEAR_ASSERT(skb);
	skb->tail += len;
	skb->len  += len;
	if (unlikely(skb->tail > skb->end))
		skb_over_panic(skb, len, __builtin_return_address(0));
	return tmp;
}

void kfree_skb(struct sk_buff *skb) /* <=== kfree_skb */ 
{
	if (unlikely(!skb))
		return;
	if (likely(atomic_read(&skb->users) == 1))
		smp_rmb();
	else if (likely(!atomic_dec_and_test(&skb->users)))
		return;
	trace_kfree_skb(skb, __builtin_return_address(0));
	__kfree_skb(skb);
}

